const $=(selector,parent=document)=>parent.querySelector(selector);
const $$=(selector,parent=document)=>[...parent.querySelectorAll(selector)];
const LOCAL_API='http://127.0.0.1:8000/api';
const isLocalHost=['localhost','127.0.0.1'].includes(window.location.hostname);
const API=(window.INTERVUE_CONFIG?.apiUrl||(isLocalHost?LOCAL_API:'')).replace(/\/$/,'');
const SESSION_KEY='intervueSession';
const state={user:null,session:null,cv:null,config:null,answers:[],questions:[],questionIndex:0,interviewId:null,report:null,authMode:'login',busy:false,voice:null};

function setStatus(message,type='info',target=$('#globalStatus')){if(!target)return;target.textContent=message;target.dataset.type=type;target.hidden=!message;}
function setBusy(busy,label='Working…'){state.busy=busy;$('#syncStatus').textContent=busy?label:'';}
function saveSession(payload){state.session={access_token:payload.access_token,refresh_token:payload.refresh_token,expires_at:Date.now()+(payload.expires_in||3600)*1000};localStorage.setItem(SESSION_KEY,JSON.stringify(state.session));}
function clearSession(){localStorage.removeItem(SESSION_KEY);state.session=null;state.user=null;}
function readSession(){try{const parsed=JSON.parse(localStorage.getItem(SESSION_KEY));if(parsed?.access_token&&parsed?.refresh_token)state.session=parsed;}catch{clearSession();}}

async function rawRequest(path,options={}){if(!API)throw new Error('The production API URL has not been configured yet.');const headers={...(options.headers||{})};if(options.body&&!(options.body instanceof FormData))headers['Content-Type']='application/json';if(state.session?.access_token)headers.Authorization=`Bearer ${state.session.access_token}`;return fetch(`${API}${path}`,{...options,headers});}
async function refreshSession(){if(!state.session?.refresh_token)return false;const response=await rawRequest('/auth/refresh',{method:'POST',body:JSON.stringify({refresh_token:state.session.refresh_token}),headers:{}});if(!response.ok){clearSession();return false;}saveSession(await response.json());return true;}
async function api(path,options={},retry=true){let response;try{response=await rawRequest(path,options);}catch{throw new Error('Cannot reach the INTERVUE API. Confirm the FastAPI server is running.');}if(response.status===401&&retry&&state.session?.refresh_token){if(await refreshSession())return api(path,options,false);clearSession();closeApp();openAuth('Your session expired. Please sign in again.');throw new Error('Your session expired.');}if(!response.ok){let message=`Request failed (${response.status}).`;try{const body=await response.json();message=body.error?.message||body.detail||body.message||message;}catch{}throw new Error(message);}if(response.status===204)return null;return response.json();}

const authDialog=$('#authDialog');
function openAuth(message=''){setStatus(message,message?'error':'info',$('#authStatus'));authDialog.showModal();}
$$('[data-action="open-auth"]').forEach(button=>button.addEventListener('click',()=>state.user?openApp():openAuth()));
$('[data-action="close-auth"]').onclick=()=>authDialog.close();
function setAuthMode(mode){state.authMode=mode;const recovery=mode==='reset';$('.auth-tabs').hidden=recovery;$$('[data-auth-mode]').forEach(item=>item.classList.toggle('active',item.dataset.authMode===mode));$('#nameLabel').hidden=mode!=='register';$('#name').required=mode==='register';$('#email').closest('label').hidden=recovery;$('#email').required=!recovery;$('#password').autocomplete=mode==='login'?'current-password':'new-password';$('#authSubmit').childNodes[0].textContent=mode==='register'?'Create account ':recovery?'Update password ':'Sign in ';$('#resetPassword').hidden=recovery;setStatus('','info',$('#authStatus'));}
$$('[data-auth-mode]').forEach(button=>button.onclick=()=>setAuthMode(button.dataset.authMode));

$('#authForm').addEventListener('submit',async event=>{event.preventDefault();if(state.busy)return;setBusy(true,state.authMode==='register'?'Creating account…':state.authMode==='reset'?'Updating password…':'Signing in…');setStatus('','info',$('#authStatus'));try{if(state.authMode==='reset'){const result=await api('/auth/password-update',{method:'POST',body:JSON.stringify({password:$('#password').value})},false);setStatus(result.message,'success',$('#authStatus'));await restoreUser();setTimeout(()=>{authDialog.close();openApp();},500);return;}const body={email:$('#email').value.trim(),password:$('#password').value};if(state.authMode==='register')body.name=$('#name').value.trim();const result=await api(`/auth/${state.authMode}`,{method:'POST',body:JSON.stringify(body)},false);if(!result.access_token){setStatus(result.message||'Check your email to confirm your account.','success',$('#authStatus'));return;}saveSession(result);await restoreUser();authDialog.close();openApp();}catch(error){setStatus(error.message,'error',$('#authStatus'));}finally{setBusy(false);}});

$('#resetPassword').onclick=async()=>{const email=$('#email').value.trim();if(!email){setStatus('Enter your email address first.','error',$('#authStatus'));return;}setBusy(true,'Sending reset…');try{const result=await api('/auth/password-reset',{method:'POST',body:JSON.stringify({email,redirect_to:`${location.origin}${location.pathname}`})},false);setStatus(result.message,'success',$('#authStatus'));}catch(error){setStatus(error.message,'error',$('#authStatus'));}finally{setBusy(false);}};

async function restoreUser(){if(!state.session)return false;try{state.user=await api('/me');$$('[data-action="open-auth"]').forEach(button=>button.textContent='Open workspace');return true;}catch{return false;}}
function openApp(){document.body.style.overflow='hidden';$('#appShell').hidden=false;$('.candidate-name').textContent=state.user?.name||state.user?.email||'Candidate';showScreen('profile');loadCvs();}
function closeApp(){if(state.voice){state.voice.ending=true;state.voice.socket?.close();stopVoiceMedia();state.voice=null;}$('#appShell').hidden=true;document.body.style.overflow='';}
$('#exitApp').onclick=closeApp;
$('#logout').onclick=async()=>{setBusy(true,'Signing out…');try{await api('/auth/logout',{method:'POST'});}catch{}finally{clearSession();closeApp();location.reload();}};

function showScreen(name){$$('.screen').forEach(screen=>screen.classList.toggle('active',screen.dataset.screen===name));const stages=['profile','setup','interview','evaluation','history'];const index=name==='voice'?2:stages.indexOf(name);$$('.progress li').forEach((item,itemIndex)=>item.classList.toggle('active',itemIndex===index));$('#stageLabel').textContent=`0${index+1} / ${(name==='voice'?'interview':name).toUpperCase()}`;setStatus('');}
$$('[data-next]').forEach(button=>button.onclick=()=>showScreen(button.dataset.next));

async function loadCvs(){try{const cvs=await api('/cvs');if(cvs.length){state.cv=cvs[0];$('#fileStatus').textContent=`Stored privately · ${state.cv.original_name} · ${Math.ceil(state.cv.size_bytes/1024)} KB · ${state.cv.extraction_status==='complete'?'text extracted':'extraction failed'}`;$('.next').disabled=false;$('#deleteCv').hidden=false;}}catch(error){setStatus(error.message,'error');}}
$('#cvFile').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;if(file.size>5*1024*1024){$('#fileStatus').textContent='File is larger than 5 MB.';return;}setBusy(true,'Uploading CV…');$('#fileStatus').textContent='Validating, extracting, and storing privately…';try{const data=new FormData();data.append('file',file);state.cv=await api('/cvs',{method:'POST',body:data});$('#fileStatus').textContent=`Stored privately · ${state.cv.original_name} · ${Math.ceil(state.cv.size_bytes/1024)} KB · ${state.cv.extraction_status==='complete'?'text extracted':state.cv.extraction_error}`;$('.next').disabled=false;$('#deleteCv').hidden=false;}catch(error){$('#fileStatus').textContent=error.message;$('.next').disabled=true;}finally{setBusy(false);}});
$('#deleteCv').onclick=async()=>{if(!state.cv||!confirm('Delete this stored CV? Existing interview records will remain.'))return;setBusy(true,'Deleting CV…');try{await api(`/cvs/${state.cv.id}`,{method:'DELETE'});state.cv=null;$('#cvFile').value='';$('#fileStatus').textContent='No file selected';$('.next').disabled=true;$('#deleteCv').hidden=true;}catch(error){setStatus(error.message,'error');}finally{setBusy(false);}};

function readInterviewConfig(mode='text'){const role=$('#role').value.trim();if(!role){$('#role').focus();return null;}return{role,seniority:$('#seniority').value,focus:$('#focus').value,duration_questions:Number($('#length').value),cv_id:state.cv?.id||null,mode};}
$('#beginInterview').onclick=async()=>{state.config=readInterviewConfig('text');if(!state.config)return;setBusy(true,'Creating interview…');try{const interview=await api('/interviews',{method:'POST',body:JSON.stringify(state.config)});loadInterview(interview);}catch(error){setStatus(error.message,'error');}finally{setBusy(false);}};
$('#beginVoiceInterview').onclick=async()=>{const config=readInterviewConfig('voice');if(!config)return;await startVoiceInterview(config);};
function loadInterview(interview){state.interviewId=interview.id;state.config=interview;state.questions=interview.questions||[];state.answers=interview.answers||[];state.questionIndex=interview.current_question_index||state.answers.length;$('#interviewRole').textContent=`${interview.role} · ${interview.seniority}`;$('#chat').innerHTML='';state.answers.forEach(answer=>{const question=state.questions.find(item=>item.id===answer.question_id);if(question)addMessage('ai',question.question_text,'INTERVUE');addMessage('user',answer.answer_text,'YOU');});showScreen('interview');askCurrent();}
function askCurrent(){const question=state.questions[state.questionIndex];if(!question){completeInterview();return;}$('#questionCount').textContent=`Question ${state.questionIndex+1} of ${state.questions.length}`;addMessage('ai',question.question_text,'INTERVUE');}
function addMessage(type,text,label){const element=document.createElement('div');element.className=`message ${type}`;const small=document.createElement('small');small.textContent=label;const content=document.createElement('div');content.textContent=text;element.append(small,content);$('#chat').append(element);$('#chat').scrollTop=$('#chat').scrollHeight;}
$('#answer').addEventListener('input',event=>$('#wordCount').textContent=`${event.target.value.trim()?event.target.value.trim().split(/\s+/).length:0} words`);
$('#answerForm').addEventListener('submit',async event=>{event.preventDefault();const text=$('#answer').value.trim();if(!text||state.busy)return;setBusy(true,'Saving answer…');try{const answer=await api(`/interviews/${state.interviewId}/answers`,{method:'POST',body:JSON.stringify({answer:text})});state.answers.push(answer);addMessage('user',text,'YOU');$('#answer').value='';$('#wordCount').textContent='0 words';state.questionIndex+=1;if(state.questionIndex<state.questions.length)askCurrent();else await completeInterview();}catch(error){setStatus(error.message,'error');}finally{setBusy(false);}});

async function completeInterview(){setBusy(true,'Building heuristic report…');try{state.report=await api(`/interviews/${state.interviewId}/complete`,{method:'POST'});renderEvaluation(state.report);}catch(error){setStatus(error.message,'error');}finally{setBusy(false);}}
function renderEvaluation(report){showScreen('evaluation');const evaluation=report.evaluation||report;const scores=evaluation.scores||{};const ai=evaluation.evaluation_type!=='heuristic';const details=evaluation.details||{};const provider=evaluation.evaluation_type==='groq'?'Groq':'Gemini';const answerCount=(report.answers||state.answers).length||((report.transcript||[]).filter(turn=>turn.speaker==='candidate').length);$('#summary').textContent=ai?`${details.coaching_summary||`${provider} generated transcript-grounded coaching.`} Overall ${evaluation.overall_score}/100 AI-generated estimate. ${evaluation.notice}`:`This heuristic rubric found an overall ${evaluation.overall_score}/100 signal across ${answerCount} answers. ${evaluation.notice}`;$('#scoreGrid').innerHTML=Object.entries(scores).map(([key,value])=>`<div class="score"><b>${value}</b><span>${key.replaceAll('_',' ')}</span></div>`).join('');const list=$('#evidenceList');list.innerHTML='';if(ai){[['Strengths',details.strengths],['Improvement opportunities',details.improvement_opportunities],['Suggested practice topics',details.practice_topics],['Missing evidence',details.missing_evidence]].forEach(([title,items])=>{if(!items?.length)return;const box=document.createElement('div');box.className='evidence';const heading=document.createElement('b');heading.textContent=title;const paragraph=document.createElement('p');paragraph.textContent=items.join(' · ');box.append(heading,paragraph);list.append(box);});}(report.answers||state.answers).forEach((answer,index)=>{const box=document.createElement('div');box.className='evidence';const excerpt=answer.answer_text.length>220?`${answer.answer_text.slice(0,217)}…`:answer.answer_text;const heading=document.createElement('b');heading.textContent=`Q${index+1} · ${answer.word_count||answer.answer_text.split(/\s+/).length} words`;const paragraph=document.createElement('p');paragraph.textContent=`“${excerpt}”`;box.append(heading,paragraph);list.append(box);});(report.transcript||[]).forEach(turn=>{const box=document.createElement('div');box.className='evidence';const heading=document.createElement('b');heading.textContent=`${turn.speaker==='candidate'?'YOU':'INTERVUE'} · TURN ${Number(turn.position)+1}`;const paragraph=document.createElement('p');paragraph.textContent=turn.content;box.append(heading,paragraph);list.append(box);});}
$('#restart').onclick=()=>showScreen('setup');
$('#downloadReport').onclick=()=>{if(!state.report)return;const blob=new Blob([JSON.stringify({product:'INTERVUE',generatedAt:new Date().toISOString(),notice:'Practice coaching report. AI scores are estimates, not objective measurements or hiring recommendations.',...state.report},null,2)],{type:'application/json'});const anchor=document.createElement('a');anchor.href=URL.createObjectURL(blob);anchor.download='intervue-practice-report.json';anchor.click();URL.revokeObjectURL(anchor.href);};

function resamplePcm16(floatSamples,inputRate,targetRate=16000){if(inputRate===targetRate){const direct=new Int16Array(floatSamples.length);for(let i=0;i<floatSamples.length;i++)direct[i]=Math.max(-1,Math.min(1,floatSamples[i]))*0x7fff;return direct;}const ratio=inputRate/targetRate;const length=Math.floor(floatSamples.length/ratio);const output=new Int16Array(length);for(let i=0;i<length;i++){const start=Math.floor(i*ratio),end=Math.min(floatSamples.length,Math.floor((i+1)*ratio));let total=0;for(let j=start;j<end;j++)total+=floatSamples[j];const sample=total/Math.max(1,end-start);output[i]=Math.max(-1,Math.min(1,sample))*0x7fff;}return output;}
function setVoiceConnection(label,status=''){const pill=$('#voiceConnection');pill.lastChild.textContent=` ${label}`;pill.dataset.state=status;}
function addTranscriptDelta(speaker,text){const panel=$('#voiceTranscript');$('.empty-state',panel)?.remove();let turn=panel.lastElementChild;if(!turn||!turn.classList.contains(speaker)||turn.dataset.complete==='true'){turn=document.createElement('div');turn.className=`transcript-turn ${speaker}`;turn.innerHTML='<small></small><p></p>';turn.querySelector('small').textContent=speaker==='interviewer'?'INTERVUE':'YOU';panel.append(turn);}turn.querySelector('p').textContent+=text;if(speaker==='interviewer'){const content=turn.querySelector('p').textContent;$('#currentVoiceQuestion').textContent=content;$('#aiState').textContent='Speaking';}panel.scrollTop=panel.scrollHeight;}
function markTranscriptComplete(saved=[]){const last=$('#voiceTranscript').lastElementChild;if(last)last.dataset.complete='true';const candidateCount=$$('.transcript-turn.candidate',$('#voiceTranscript')).length;$('#voiceProgress').textContent=`${candidateCount} RESPONSE${candidateCount===1?'':'S'} SAVED`;$('#transcriptStatus').textContent=saved.length?'Saved securely':'Waiting for next turn';}
function stopVoiceMedia(){const voice=state.voice;if(!voice)return;clearInterval(voice.timer);cancelAnimationFrame(voice.meterFrame);voice.stream?.getTracks().forEach(track=>track.stop());voice.processor?.disconnect();voice.analyser?.disconnect();voice.micSource?.disconnect();voice.silentGain?.disconnect();voice.sources?.forEach(source=>{try{source.stop();}catch{}});voice.audioContext?.close().catch(()=>{});}
function updateMicMeter(){const voice=state.voice;if(!voice?.analyser)return;const samples=new Uint8Array(voice.analyser.fftSize);voice.analyser.getByteTimeDomainData(samples);let sum=0;for(const value of samples){const normalized=(value-128)/128;sum+=normalized*normalized;}const level=voice.muted?0:Math.min(100,Math.sqrt(sum/samples.length)*280);$('#candidateMeter').style.setProperty('--level',`${level}%`);voice.meterFrame=requestAnimationFrame(updateMicMeter);}
function showAiLevel(bytes){const view=new Int16Array(bytes);let sum=0;for(const value of view)sum+=(value/32768)**2;const level=Math.min(1,Math.sqrt(sum/Math.max(1,view.length))*4);const factors=[.45,.72,1,.6,.84,.52,.92,.68];$$('#aiOrb span').forEach((bar,index)=>bar.style.height=`${Math.max(8,level*120*factors[index])}px`);$('#aiOrb').dataset.active=level>.02?'true':'false';clearTimeout(state.voice.aiDecay);state.voice.aiDecay=setTimeout(()=>{$('#aiOrb').dataset.active='false';$('#aiState').textContent='Listening';},180);}
function playPcm(bytes){const voice=state.voice;if(!voice?.audioContext)return;showAiLevel(bytes);const input=new Int16Array(bytes),floats=new Float32Array(input.length);for(let i=0;i<input.length;i++)floats[i]=input[i]/32768;const buffer=voice.audioContext.createBuffer(1,floats.length,24000);buffer.copyToChannel(floats,0);const source=voice.audioContext.createBufferSource();source.buffer=buffer;source.connect(voice.audioContext.destination);voice.sources.add(source);source.onended=()=>voice.sources.delete(source);const start=Math.max(voice.audioContext.currentTime+.015,voice.playAt||0);source.start(start);voice.playAt=start+buffer.duration;}
async function openVoiceSocket(){const voice=state.voice;if(!voice||voice.ending)return;const ticket=await api(`/voice/sessions/${state.interviewId}`,{method:'POST'});const apiUrl=new URL(API);const wsUrl=`${apiUrl.protocol==='https:'?'wss:':'ws:'}//${apiUrl.host}${ticket.websocket_path}`;const socket=new WebSocket(wsUrl);socket.binaryType='arraybuffer';voice.socket=socket;socket.onopen=()=>{voice.retries=0;setVoiceConnection('CONNECTED','connected');$('#micState').textContent=voice.muted?'Muted':'Listening';};socket.onmessage=event=>{if(event.data instanceof ArrayBuffer){playPcm(event.data);return;}const message=JSON.parse(event.data);if(message.type==='connected'){$('#aiState').textContent='Introducing the interview';return;}if(message.type==='transcript_delta'){addTranscriptDelta(message.speaker,message.text);return;}if(message.type==='turn_complete'){markTranscriptComplete(message.saved);$('#aiState').textContent='Listening';return;}if(message.type==='interrupted'){voice.sources.forEach(source=>{try{source.stop();}catch{}});voice.sources.clear();voice.playAt=0;$('#aiState').textContent='Listening';return;}if(message.type==='reconnect_required')setVoiceConnection('RECONNECTING');if(message.type==='error')setStatus(message.message,'error');};socket.onerror=()=>setVoiceConnection('CONNECTION ISSUE','error');socket.onclose=async()=>{if(voice.ending)return;if(voice.retries<2){voice.retries+=1;setVoiceConnection('RECONNECTING');setTimeout(()=>openVoiceSocket().catch(error=>setStatus(error.message,'error')),800*voice.retries);}else{setVoiceConnection('DISCONNECTED','error');setStatus('The live connection ended. Your saved transcript is safe; end the interview or try again.','error');}};}
async function prepareMicrophone(){if(!navigator.mediaDevices?.getUserMedia)throw new Error('This browser does not support microphone capture. Use a current browser over localhost or HTTPS.');let stream;try{stream=await navigator.mediaDevices.getUserMedia({audio:{channelCount:1,echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});}catch(error){if(error.name==='NotAllowedError')throw new Error('Microphone permission was denied. Allow microphone access in your browser, then try again.');if(error.name==='NotFoundError')throw new Error('No microphone was found. Connect one and try again.');throw new Error('The microphone could not be started. Check browser and system audio permissions.');}const AudioContext=window.AudioContext||window.webkitAudioContext;const context=new AudioContext();await context.resume();const source=context.createMediaStreamSource(stream);const analyser=context.createAnalyser();analyser.fftSize=512;source.connect(analyser);const processor=context.createScriptProcessor(4096,1,1);source.connect(processor);const silent=context.createGain();silent.gain.value=0;processor.connect(silent);silent.connect(context.destination);return{stream,audioContext:context,micSource:source,analyser,processor,silentGain:silent};}
async function startVoiceInterview(config,existing=null){if(state.busy)return;setBusy(true,'Requesting microphone…');try{const audio=await prepareMicrophone();let interview=existing;if(!interview){state.config=config;interview=await api('/interviews',{method:'POST',body:JSON.stringify(config)});}state.interviewId=interview.id;state.config=interview;state.voice={...audio,muted:false,ending:false,retries:0,sources:new Set(),playAt:0,startedAt:Date.now(),timer:null,meterFrame:null,aiDecay:null};audio.processor.onaudioprocess=event=>{const voice=state.voice;if(!voice||voice.muted||voice.socket?.readyState!==WebSocket.OPEN)return;const pcm=resamplePcm16(event.inputBuffer.getChannelData(0),voice.audioContext.sampleRate);if(pcm.byteLength)voice.socket.send(pcm.buffer);};$('#voiceRole').textContent=`${interview.role} · ${interview.seniority}`;$('#voiceTranscript').innerHTML='<p class="empty-state">Connecting to your interviewer…</p>';showScreen('voice');updateMicMeter();state.voice.timer=setInterval(()=>{const elapsed=Math.floor((Date.now()-state.voice.startedAt)/1000);$('#voiceTimer').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(elapsed%60).padStart(2,'0')}`;},1000);await openVoiceSocket();}catch(error){stopVoiceMedia();state.voice=null;setStatus(error.message,'error');showScreen('setup');}finally{setBusy(false);}}
$('#toggleMute').onclick=()=>{const voice=state.voice;if(!voice)return;voice.muted=!voice.muted;voice.stream.getAudioTracks().forEach(track=>track.enabled=!voice.muted);$('#toggleMute').textContent=voice.muted?'Unmute':'Mute';$('#toggleMute').setAttribute('aria-pressed',String(voice.muted));$('#micState').textContent=voice.muted?'Muted':'Listening';};
$('#endVoiceInterview').onclick=async()=>{const voice=state.voice;if(!voice||voice.ending)return;voice.ending=true;setBusy(true,'Saving interview…');try{if(voice.socket?.readyState===WebSocket.OPEN){voice.socket.send(JSON.stringify({type:'end'}));await new Promise(resolve=>setTimeout(resolve,700));voice.socket.close(1000,'Candidate ended interview');}stopVoiceMedia();state.report=await api(`/voice/sessions/${state.interviewId}/complete`,{method:'POST'});renderEvaluation(state.report);if(state.report.warning)setStatus(state.report.warning,'error');}catch(error){setStatus(error.message,'error');}finally{state.voice=null;setBusy(false);}};

$('#showHistory').onclick=loadHistory;
async function loadHistory(){showScreen('history');$('#historyList').innerHTML='<p class="empty-state">Loading interview history…</p>';try{const sessions=await api('/interviews');if(!sessions.length){$('#historyList').innerHTML='<p class="empty-state">No interviews yet. Your next practice session will appear here.</p>';return;}$('#historyList').innerHTML='';sessions.forEach(session=>{const card=document.createElement('article');card.className='history-card';card.innerHTML=`<div><p class="eyebrow">${session.status==='completed'?'Completed':'In progress'}</p><h3></h3><span></span></div><button class="ghost-btn">${session.status==='completed'?'View report':'Resume'}</button>`;card.querySelector('h3').textContent=session.role;card.querySelector('span').textContent=`${session.seniority} · ${session.focus} · ${new Date(session.created_at).toLocaleDateString()}`;card.querySelector('button').onclick=()=>openHistoryItem(session);$('#historyList').append(card);});}catch(error){$('#historyList').innerHTML='<p class="empty-state"></p>';$('#historyList p').textContent=error.message;}}
async function openHistoryItem(session){setBusy(true,'Loading session…');try{if(session.status==='completed'){state.interviewId=session.id;state.report=await api(`/interviews/${session.id}/report`);renderEvaluation(state.report);}else{const interview=await api(`/interviews/${session.id}`);if(interview.mode==='voice'){setBusy(false);await startVoiceInterview(null,interview);}else loadInterview(interview);}}catch(error){setStatus(error.message,'error');}finally{setBusy(false);}}

(async function boot(){const recovery=new URLSearchParams(location.hash.slice(1));if(recovery.get('type')==='recovery'&&recovery.get('access_token')&&recovery.get('refresh_token')){saveSession({access_token:recovery.get('access_token'),refresh_token:recovery.get('refresh_token'),expires_in:Number(recovery.get('expires_in')||3600)});history.replaceState(null,'',location.pathname+location.search);setAuthMode('reset');openAuth('Choose a new password to finish account recovery.');return;}readSession();if(state.session&&await restoreUser())$$('[data-action="open-auth"]').forEach(button=>button.textContent='Open workspace');else if(state.session)clearSession();})();

